import{_ as t,o as h,c as i,a2 as c}from"./chunks/framework.CqpfiAoK.js";const e=JSON.parse('{"title":"Thời kỳ Tiền-neo","description":"","frontmatter":{},"headers":[],"relativePath":"vi/71-前锚点时代.md","filePath":"vi/71-前锚点时代.md","lastUpdated":null}'),g={name:"vi/71-前锚点时代.md"};function a(o,n,u,l,r,m){return h(),i("div",null,[...n[0]||(n[0]=[c('<h1 id="thoi-ky-tien-neo" tabindex="-1">Thời kỳ Tiền-neo <a class="header-anchor" href="#thoi-ky-tien-neo" aria-label="Permalink to &quot;Thời kỳ Tiền-neo&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>71</td></tr><tr><td>Mô-đun</td><td>Kỷ nguyên Lịch sử và Sự kiện Quan trọng</td></tr><tr><td>Từ khóa cốt lõi</td><td>Thời kỳ tiền-neo, hệ thống săn mồi, đứt gãy văn minh, kỷ nguyên tối tăm, hỗn loạn luật</td></tr></tbody></table><h2 id="_1-đac-điem-co-ban-cua-thoi-ky-tien-neo" tabindex="-1">1. Đặc điểm Cơ bản của Thời kỳ Tiền-neo <a class="header-anchor" href="#_1-đac-điem-co-ban-cua-thoi-ky-tien-neo" aria-label="Permalink to &quot;1. Đặc điểm Cơ bản của Thời kỳ Tiền-neo&quot;">​</a></h2><p>Thời kỳ Tiền-neo là kỷ nguyên dài nhất và tối tăm nhất trong lịch sử Hengyuanzhou. Trong thời kỳ này, không có cơ chế neo thống nhất trong vũ trụ, các luật cơ bản ở trạng thái phân tán tự nhiên, và việc phân phối năng lượng và tài nguyên hoàn toàn tuân theo luật rừng &quot;người mạnh được&quot;. Hệ thống tu luyện săn mồi là người thống trị tuyệt đối của thời kỳ này; các phương pháp tu luyện bị một số ít người mạnh và các phái môn độc quyền, và các sinh vật bình thường ở tầng dưới gần như không có con đường tiến hóa chính thức.</p><p>Đặc điểm cốt lõi của Thời kỳ Tiền-neo có thể được tóm tắt là &quot;năm sự vắng mặt&quot;:</p><ul><li><strong>Không có neo</strong>: Không có neo luật ổn định, dòng chảy năng lượng hỗn loạn, và các rào cản giữa các mặt phẳng mong manh</li><li><strong>Không có trật tự</strong>: Không có hệ thống văn minh thống nhất, chiến tranh liên tục giữa các mặt phẳng, và diệt chủng thường xuyên xảy ra</li><li><strong>Không có đường đi</strong>: Không có công nghệ giao tiếp và vận chuyển giữa các mặt phẳng, và các mặt phẳng về cơ bản bị cô lập với nhau</li><li><strong>Không có bảo đảm</strong>: Không có hệ thống bảo đảm công cộng như giáo dục, y tế, nhà ở, và sự tồn tại của cuộc sống hoàn toàn phụ thuộc vào sức mạnh cá nhân</li><li><strong>Không có hy vọng</strong>: Các kênh tiến hóa của sinh vật ở tầng dưới hoàn toàn bị phong tỏa, và sự phân tầng xã hội đạt đến mức cực đoan</li></ul><h2 id="_2-co-che-hoat-đong-cua-he-thong-tu-luyen-san-moi" tabindex="-1">2. Cơ chế Hoạt động của Hệ thống Tu luyện Săn mồi <a class="header-anchor" href="#_2-co-che-hoat-đong-cua-he-thong-tu-luyen-san-moi" aria-label="Permalink to &quot;2. Cơ chế Hoạt động của Hệ thống Tu luyện Săn mồi&quot;">​</a></h2><p>Hệ thống tu luyện của Thời kỳ Tiền-neo có săn mồi là cơ chế hoạt động cốt lõi. Logic cơ bản của nó là: năng lượng cơ bản của vũ trụ có hạn, và sự tiến hóa của cá nhân chắc chắn xảy ra với cái giá phải trả là tiêu thụ năng lượng của người khác. Người mạnh đạt được sự thăng tiến của chính mình bằng cách nuốt chửng năng lượng, may mắn và thậm chí bản chất của người yếu, trong khi người yếu trở thành &quot;tài nguyên tu luyện&quot; của người mạnh.</p><p>Các hình thức điển hình của hệ thống săn mồi bao gồm:</p><table tabindex="0"><thead><tr><th>Loại săn mồi</th><th>Cách thức hoạt động</th><th>Tổn hại cho vũ trụ</th></tr></thead><tbody><tr><td>Săn mồi năng lượng</td><td>Trích xuất trực tiếp năng lượng tu luyện của các sinh vật khác</td><td>Gây ra cái chết cá nhân hoặc mất đi tu vi hoàn toàn</td></tr><tr><td>Săn mồi may mắn</td><td>Thông qua thuật pháp hoặc nghi lễ, cướp đi may mắn và cơ hội của người khác</td><td>Phá hủy cân bằng nhân quả, gây ra thảm họa cấp mặt phẳng</td></tr><tr><td>Săn mồi bản chất</td><td>Nuốt chửng các mảnh luật cơ bản của các sinh vật khác</td><td>Gây ra mất đi tiềm năng tiến hóa không thể phục hồi</td></tr><tr><td>Săn mồi mặt phẳng</td><td>Người mạnh chinh phục toàn bộ mặt phẳng và sử dụng các sinh vật trên mặt phẳng làm tài nguyên tu luyện</td><td>Gây ra tuyệt chủng văn minh và sa mạc hóa mặt phẳng</td></tr><tr><td>Săn mồi luật</td><td>Cướp đoạt quyền kiểm soát luật cơ bản của một mặt phẳng</td><td>Phá hủy mạng lưới luật, gây ra sụp đổ không gian</td></tr></tbody></table><p>Hệ thống săn mồi có thể, trong ngắn hạn, tạo ra một số người mạnh nhất, nhưng trong dài hạn, nó liên tục tiêu thụ tiềm năng tiến hóa của vũ trụ, dẫn đến sự gia tăng entropy tổng thể của vũ trụ được đẩy nhanh và sự đứt gãy văn minh thường xuyên xảy ra.</p><h2 id="_3-đut-gay-van-minh-va-huy-diet-chu-ky" tabindex="-1">3. Đứt gãy Văn minh và Hủy diệt Chu kỳ <a class="header-anchor" href="#_3-đut-gay-van-minh-va-huy-diet-chu-ky" aria-label="Permalink to &quot;3. Đứt gãy Văn minh và Hủy diệt Chu kỳ&quot;">​</a></h2><p>Hiện tượng lịch sử nổi bật nhất của Thời kỳ Tiền-neo là &quot;đứt gãy văn minh&quot;. Do những mâu thuẫn nội tại của hệ thống săn mồi, mỗi nền văn minh từng rực rỡ cuối cùng đều đi đến sự tự hủy diệt:</p><ol><li><strong>Giai đoạn trỗi dậy</strong>: Một chủng tộc hoặc phái môn trỗi dậy nhanh chóng thông qua săn mồi và thiết lập một nền văn minh mạnh mẽ</li><li><strong>Giai đoạn đỉnh cao</strong>: Nền văn minh đạt đến đỉnh cao sức mạnh, đàn áp sự phản kháng bên trong, và mở rộng để săn mồi bên ngoài</li><li><strong>Giai đoạn nội chiến</strong>: Người mạnh bên trong nền văn minh chiến đấu với nhau vì tài nguyên hạn chế, tiêu thụ sức mạnh của họ</li><li><strong>Giai đoạn sụp đổ</strong>: Nội chiến làm giảm mạnh sức mạnh của nền văn minh, và những kẻ săn mồi bên ngoài tận dụng cơ hội để xâm nhập, gây ra tuyệt chủng văn minh</li><li><strong>Giai đoạn đứt gãy</strong>: Sau khi văn minh tuyệt chủng, phần lớn kiến thức và công nghệ của nó bị mất, và nền văn minh tiếp theo phải bắt đầu từ số không</li></ol><p>Chu kỳ &quot;trỗi dậy—đỉnh cao—nội chiến—sụp đổ—đứt gãy&quot; này đã lặp lại vô số lần trong Thời kỳ Tiền-neo. Mỗi chu kỳ đã tiêu thụ một lượng lớn bản chất vũ trụ, làm cho mức độ tiến hóa tổng thể của vũ trụ bị đình trệ hoặc thậm chí đi lùi trong một thời gian dài.</p><h2 id="_4-dau-hieu-cuoi-thoi-ky-tien-neo" tabindex="-1">4. Dấu hiệu Cuối Thời kỳ Tiền-neo <a class="header-anchor" href="#_4-dau-hieu-cuoi-thoi-ky-tien-neo" aria-label="Permalink to &quot;4. Dấu hiệu Cuối Thời kỳ Tiền-neo&quot;">​</a></h2><p>Vào cuối Thời kỳ Tiền-neo, vũ trụ đã xuất hiện một loạt dấu hiệu báo trước sự thay đổi:</p><ul><li><strong>Tăng cường hỗn loạn luật</strong>: Săn mồi lâu dài đã làm hỏng nghiêm trọng mạng lưới luật, các sự kiện sụp đổ không gian trở nên thường xuyên, và các rào cản giữa các mặt phẳng trở nên mỏng hơn</li><li><strong>Cạn kiệt tiềm năng sự sống</strong>: Năng lượng cơ bản có thể săn mồi ngày càng ít đi, và cuộc tranh giành tài nguyên giữa người mạnh trở nên gay gắt</li><li><strong>Mọc mầm tư tưởng chống săn mồi</strong>: Một số người có trí tuệ bắt đầu phản ánh về những khuyết điểm cơ bản của hệ thống săn mồi và đề xuất những ý tưởng ban đầu về tiến hóa cộng sinh</li><li><strong>Tăng cường tiếp xúc giữa các mặt phẳng</strong>: Việc các rào cản giữa các mặt phẳng mỏng đi đã cho phép tiếp xúc nhiều hơn giữa các mặt phẳng khác nhau, làm cho việc trao đổi tư tưởng giữa các mặt phẳng trở nên khả thi</li><li><strong>Sự xuất hiện của ứng viên neo thế hệ đầu tiên</strong>: Ở một số góc của vũ trụ, đã xuất hiện những sinh vật đặc biệt có khả năng cộng hưởng tự nhiên với mạng lưới luật; họ là tiền thân của những người đánh thức neo thế hệ đầu tiên trong tương lai</li></ul><p>Những dấu hiệu này chỉ ra rằng hệ thống săn mồi đã đến cuối con đường, và vũ trụ đang kêu gọi một hình thức văn minh hoàn toàn mới.</p><h2 id="_5-di-san-lich-su-cua-thoi-ky-tien-neo" tabindex="-1">5. Di sản Lịch sử của Thời kỳ Tiền-neo <a class="header-anchor" href="#_5-di-san-lich-su-cua-thoi-ky-tien-neo" aria-label="Permalink to &quot;5. Di sản Lịch sử của Thời kỳ Tiền-neo&quot;">​</a></h2><p>Mặc dù Thời kỳ Tiền-neo tối tăm, nó không hoàn toàn vô giá trị. Nó đã để lại một di sản lịch sử quan trọng cho nền văn minh cộng sinh neo sau này:</p><ul><li><strong>Di sản bài học</strong>: Những thất bại lặp đi lặp lại của hệ thống săn mồi đã cung cấp một bài học tiêu cực sâu sắc nhất cho nền văn minh cộng sinh, chứng minh rằng con đường săn mồi không đi đến đâu</li><li><strong>Di sản kiến thức</strong>: Mặc dù phần lớn kiến thức đã bị mất trong các đứt gãy văn minh, một số phương pháp tu luyện và sự hiểu biết về luật đã tồn tại qua nhiều cách khác nhau, trở thành nguồn vật liệu cho ba trăm hệ thống tu luyện cơ bản</li><li><strong>Di sản sự sống</strong>: Các hình thức sự sống đa dạng đã sống sót qua thời kỳ tối tăm dài đã tạo thành cơ sở chủng tộc cho cộng sinh tất cả các chủng tộc trong tương lai</li><li><strong>Di sản ý chí</strong>: Khát vọng liên tục của các sinh vật ở tầng dưới về công lý và hy vọng là động lực tinh thần cơ bản nhất cho sự thức tỉnh của neo</li></ul><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>Thời kỳ Tiền-neo là &quot;đêm trước bóng tối&quot; trong lịch sử Hengyuanzhou. Sự dài ngắn và tối tăm của nó, ngược lại, càng làm nổi bật sự quý giá và tất yếu của sự ra đời của nền văn minh cộng sinh neo. Hiểu được Thời kỳ Tiền-neo là hiểu được nguồn gốc lịch sử của lập trường cơ bản của nền văn minh cộng sinh &quot;phản đối săn mồi, ủng hộ cộng sinh&quot; — đây không phải là một bài giảng đạo đức trừu tượng, mà là một bài học máu và nước mắt được đổi lấy bằng sự hủy diệt của vô số nền văn minh.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>70-Bảng Tổng hợp Phân chia Kỷ nguyên</li><li>72-Kỷ nguyên Thức tỉnh Neo</li><li>04-Chương trình Cốt lõi Chống săn mồi</li></ul>',26)])])}const d=t(g,[["render",a]]);export{e as __pageData,d as default};
